package com.loanops.fincompass;
import com.loanops.fincompass.simulation.*;
import com.loanops.fincompass.twin.*;
import com.loanops.personal.canonical.PersonalFinanceService;
import com.loanops.api.ApiNotFoundException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.MockMvc;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;
import java.math.BigDecimal;
import java.util.*;
import static com.loanops.fincompass.simulation.SimulationModels.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("fincompass-demo")
class SimulationIntegrationTest {
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres:17.11-alpine"));
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::getJdbcUrl);r.add("spring.datasource.username",DB::getUsername);r.add("spring.datasource.password",DB::getPassword);r.add("fincompass.open-banking.encryption-key",()->Base64.getEncoder().encodeToString(new byte[32]));}
 @Autowired ScenarioService service;@Autowired FinancialTwinStore twins;@Autowired PersonalFinanceService personal;@Autowired JdbcTemplate jdbc;@Autowired MockMvc http;@Autowired ObjectMapper json;
 static final String OWNER="golden-homebuyer";
 private TwinModels.Snapshot twin(){return twins.latest(OWNER);}
 @Test void homeResultPersistsExactSnapshotVersionsAndBeforeAfterAssets(){var s=twin();var result=service.createHome(OWNER,ScenarioExamples.golden(s.financialSnapshotId()));assertThat(result.financialSnapshotId()).isEqualTo(s.financialSnapshotId());assertThat(result.calculationRuleVersion()).isEqualTo(TwinCalculator.RULE_VERSION);assertThat(result.simulationRuleVersion()).isEqualTo(SimulationEngine.RULE_VERSION);var after=result.homeResult().after();assertThat(after.get("TOTAL_ASSETS").value()).isEqualByComparingTo("710000000");assertThat(after.get("TOTAL_LIABILITIES").value()).isEqualByComparingTo("620000000");assertThat(after.get("NET_WORTH").value()).isEqualByComparingTo("90000000");assertThat(after.get("LIQUID_ASSETS").value()).isEqualByComparingTo("10000000");assertThat(after.get("EMERGENCY_FUND_MONTHS").value()).isEqualByComparingTo("4.54545455");assertThat(after.get("MONTHLY_FREE_CASHFLOW").value()).isEqualByComparingTo("-1789443.33");assertThat(result.homeResult().mortgage().regularMonthlyPayment()).isEqualByComparingTo("2989443.33");assertThat(result.homeResult().mortgage().totalInterest()).isEqualByComparingTo("486199597.17");assertThat(after.get("DEBT_SERVICE_BURDEN").value()).isEqualByComparingTo("0.65262606");assertThat(service.get(OWNER,result.scenarioId())).isEqualTo(result);assertThat(twins.get(OWNER,s.financialSnapshotId())).isEqualTo(s);}
 @Test void loanUsesSamePureEngineAndStoresAssumptions(){var s=twin();var input=new LoanInput(new BigDecimal("590000000"),new BigDecimal("0.045"),360,RepaymentType.AMORTIZING);var persisted=service.createLoan(OWNER,s.financialSnapshotId(),input);var expected=new SimulationEngine().loan(input,new LoanContext(s.result().monthlyDebtService(),s.result().verifiedAnnualIncome()));assertThat(persisted.loanResult()).isEqualTo(expected);assertThat(service.get(OWNER,persisted.scenarioId()).loanInput()).isEqualTo(input);}
 @Test void stressPreservesBaseAndHasRequestedGrid(){var base=service.createHome(OWNER,ScenarioExamples.golden(twin().financialSnapshotId()));var stress=service.stress(OWNER,base.scenarioId(),null);assertThat(stress.parentScenarioId()).isEqualTo(base.scenarioId());assertThat(stress.stressResults()).hasSize(SimulationEngine.defaultShocks().size());assertThat(stress.stressResults()).anySatisfy(c->{assertThat(c.shock().rateDelta()).isEqualByComparingTo("0.02");assertThat(c.result().mortgage().regularMonthlyPayment()).isGreaterThan(base.homeResult().mortgage().regularMonthlyPayment());});assertThat(service.get(OWNER,base.scenarioId())).isEqualTo(base);assertThat(service.get(OWNER,stress.scenarioId())).isEqualTo(stress);}
 @Test void fourExplicitAlternativesShareSchemaAndPreserveAdjustments(){var id=twin().financialSnapshotId();var scenarios=ScenarioExamples.alternatives(id).stream().map(input->service.createHome(OWNER,input)).toList();var comparison=service.compare(OWNER,scenarios.stream().map(ScenarioRecords.Scenario::scenarioId).toList());assertThat(comparison.comparisonResults()).hasSize(4);var all=comparison.comparisonResults();for(var value:all)assertThat(value.after().keySet()).isEqualTo(all.getFirst().after().keySet());assertThat(all.get(2).after().get("TOTAL_LIABILITIES").value()).isEqualByComparingTo("620000000");assertThat(all.get(2).after().get("MONTHLY_DEBT_SERVICE").value()).isEqualByComparingTo(all.get(2).mortgage().regularMonthlyPayment());assertThat(all.get(3).after().get("NET_WORTH").value()).isEqualByComparingTo("104400000");assertThat(all.get(3).input().adjustment().delayMonths()).isEqualTo(12);assertThat(service.get(OWNER,comparison.scenarioId())).isEqualTo(comparison);}
 @Test void repeatedCalculationsHaveIdenticalResultsDespiteSeparateAuditIds(){var input=ScenarioExamples.golden(twin().financialSnapshotId());var a=service.createHome(OWNER,input);var b=service.createHome(OWNER,input);assertThat(a.homeResult()).isEqualTo(b.homeResult());assertThat(a.scenarioId()).isNotEqualTo(b.scenarioId());}
 @Test void anotherOwnerCannotReadScenarioOrUseItsSnapshot(){var a=service.createHome(OWNER,ScenarioExamples.golden(twin().financialSnapshotId()));personal.createDemoUser("scenario-other");assertThatThrownBy(()->service.get("scenario-other",a.scenarioId())).isInstanceOf(ApiNotFoundException.class);assertThatThrownBy(()->service.createHome("scenario-other",a.homeInput())).isInstanceOf(ApiNotFoundException.class);}
 @Test void unknownAndInvalidFinancingAreSafeErrors()throws Exception{var id=twin().financialSnapshotId();var request=ScenarioExamples.golden(id);var bad=new HomeInput(id,request.housePrice(),request.cashContribution(),new BigDecimal("1"),request.annualInterestRate(),request.termMonths(),request.repaymentType(),request.explicitCosts(),request.adjustment());http.perform(post("/api/v1/scenarios/home-purchase").contentType("application/json").content(json.writeValueAsString(bad))).andExpect(status().isBadRequest());http.perform(get("/api/v1/scenarios/"+UUID.randomUUID())).andExpect(status().isNotFound());}
 @Test void homeStressCompareHttpRoundtripExposesEvidence()throws Exception{var body=json.writeValueAsString(ScenarioExamples.golden(twin().financialSnapshotId()));var response=http.perform(post("/api/v1/scenarios/home-purchase").contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.homeResult.after.LIQUID_ASSETS.value").value(10000000)).andExpect(jsonPath("$.simulationRuleVersion").value(SimulationEngine.RULE_VERSION)).andReturn().getResponse().getContentAsString();String id=json.readTree(response).get("scenarioId").asText();http.perform(post("/api/v1/scenarios/"+id+"/stress-test").contentType("application/json").content("{}")).andExpect(status().isOk()).andExpect(jsonPath("$.stressResults").isArray());http.perform(get("/api/v1/scenarios/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.homeInput.housePrice").value(700000000));}
 @Test void scenarioHistoryAndAssumptionsAreEncryptedAndImmutable(){var value=service.createHome(OWNER,ScenarioExamples.golden(twin().financialSnapshotId()));for(String table:List.of("scenario_result","scenario_assumption")){String body=jdbc.queryForObject("SELECT payload_ciphertext FROM loanops."+table+" WHERE scenario_id=?",String.class,value.scenarioId());assertThat(body).doesNotContain("700000000","housePrice","2989443");assertThatThrownBy(()->jdbc.update("DELETE FROM loanops."+table+" WHERE scenario_id=?",value.scenarioId())).isInstanceOf(org.springframework.dao.DataAccessException.class);}assertThat(service.get(OWNER,value.scenarioId())).isEqualTo(value);}
 @Test void consumerPostCorsIsAllowedAndAdminRemainsReadOnly()throws Exception{http.perform(options("/api/v1/scenarios/home-purchase").header("Origin","http://localhost:5173").header("Access-Control-Request-Method","POST").header("Access-Control-Request-Headers","content-type")).andExpect(status().isOk()).andExpect(header().string("Access-Control-Allow-Origin","http://localhost:5173"));http.perform(options("/api/v1/overview").header("Origin","http://localhost:5173").header("Access-Control-Request-Method","POST")).andExpect(status().isForbidden());}
 @Test void comparisonRejectsDuplicateOrTooFewScenarios(){var scenario=service.createHome(OWNER,ScenarioExamples.golden(twin().financialSnapshotId()));assertThatThrownBy(()->service.compare(OWNER,List.of(scenario.scenarioId()))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.compare(OWNER,List.of(scenario.scenarioId(),scenario.scenarioId()))).isInstanceOf(IllegalArgumentException.class);}
}
